/**
 * Best existing resolution for an image that the wiki already references.
 *
 * `src/data/image-variants.json` is generated by
 * `apps/shenron/bot/scripts/assets-variantes.ts` from the asset inventory: for every DB
 * path referenced by an image column it records the measured dimensions and,
 * when the SAME picture (identical dHash) exists at a larger resolution under a
 * servable path, that larger variant. Nothing here invents an image: a path that
 * is not in the map is served as is.
 *
 * Server-only by intent (the map is a few hundred KB); the chosen path is passed
 * to client components as a plain string.
 */
import { bestVariant, type ImageVariant } from "@shenron/images/variants";
import variantsJson from "@/data/image-variants.json";

interface VariantRecord {
	w: number;
	h: number;
	/** A larger copy of the same picture, when one exists. */
	best?: { path: string; w: number; h: number };
}

const VARIANTS = variantsJson as Record<string, VariantRecord>;

const key = (p: string) => p.trim().replace(/^\.?\/+/, "");

/** Known dimensions of a DB path, or null. */
function knownDimensions(path: string | null | undefined): { w: number; h: number } | null {
	if (!path) return null;
	const r = VARIANTS[key(path)];
	return r ? { w: r.w, h: r.h } : null;
}

/**
 * Picks the best resolution among candidate DB paths (and their recorded larger
 * variants). Candidates whose dimensions are unknown keep their order of
 * preference: the first one wins unless a MEASURED candidate exists — so an
 * editorial image is never displaced by a guess.
 */
export function pickBestImage(candidates: readonly (string | null | undefined)[]): string | null {
	const present = candidates.filter((c): c is string => !!c && c.trim().length > 0);
	if (!present.length) return null;
	const measured: ImageVariant[] = [];
	for (const c of present) {
		const r = VARIANTS[key(c)];
		if (!r) continue;
		measured.push({ path: c, width: r.w, height: r.h });
		if (r.best) measured.push({ path: r.best.path, width: r.best.w, height: r.best.h });
	}
	if (!measured.length) return present[0]!;
	// The first candidate is the editorial choice: only a strictly larger picture
	// (on both axes) may replace it.
	const first = measured.find((m) => m.path === present[0]);
	const best = bestVariant(measured);
	if (!best) return present[0]!;
	if (first && !((best.width ?? 0) > (first.width ?? 0) && (best.height ?? 0) >= (first.height ?? 0)))
		return present[0]!;
	return best.path;
}
